// Copyright 2026 ReC Sandbox. Scene-referred pipeline, stage S6 (SceneReferredSpec.md).#include "StdAfx.h"#include "ExrImage.h"#include <tinyexr.h>#include <vector>namespace{//! EXR is little-endian on the wire and every platform this builds for is little-endian, so the//! payloads below are memcpy'd as they sit. If that ever stops being true, this is the one place//! that has to learn to byte-swap.static_assert(sizeof(float) == 4, "EXR float attributes are 4 bytes");static_assert(sizeof(CryHalf) == 2, "EXR half channels are 2 bytes");//! An attribute payload owned for the duration of the write. tinyexr's EXRAttribute holds a raw//! pointer it does not copy, so the bytes have to outlive SaveEXRImageToMemory.struct SAttrPayload{	std::vector<unsigned char> bytes;};void PushAttribute(std::vector<EXRAttribute>& attrs, std::vector<SAttrPayload>& payloads,                   const char* szName, const char* szType, const void* pData, int nSize){	if (attrs.size() >= TINYEXR_MAX_CUSTOM_ATTRIBUTES)		return;	payloads.push_back(SAttrPayload());	SAttrPayload& payload = payloads.back();	payload.bytes.resize((size_t)nSize);	if (nSize > 0)		memcpy(payload.bytes.data(), pData, (size_t)nSize);	EXRAttribute a;	memset(&a, 0, sizeof(a));	cry_strcpy(a.name, sizeof(a.name), szName);	cry_strcpy(a.type, sizeof(a.type), szType);	a.size = nSize;	a.value = nullptr;	attrs.push_back(a);}//! The payload vectors reallocate while attributes are being pushed, so the value pointers are//! bound in a second pass, once the payload array is final.void BindAttributePayloads(std::vector<EXRAttribute>& attrs, std::vector<SAttrPayload>& payloads){	for (size_t i = 0; i < attrs.size(); ++i)		attrs[i].value = payloads[i].bytes.empty() ? nullptr : payloads[i].bytes.data();}bool WriteFileThroughPak(const char* szFileName, const unsigned char* pData, size_t size){	// ICryPak rather than the CRT. WriteTIF's TIFFOpen (TifImage.cpp:19) bypasses the pak system	// entirely, which is why every one of its callers has to build an absolute path by hand.	FILE* pFile = gEnv->pCryPak->FOpen(szFileName, "wb", ICryPak::FOPEN_ONDISK);	if (!pFile)		return false;	const size_t written = gEnv->pCryPak->FWrite(pData, 1, size, pFile);	gEnv->pCryPak->FClose(pFile);	return written == size;}} // anonymous namespacebool WriteEXR(const char* szFileName, int width, int height, const CryHalf* pRGBA, int srcRowStrideTexels, const SExrWriteDesc& desc){	if (!szFileName || !pRGBA || width <= 0 || height <= 0 || srcRowStrideTexels < width)		return false;	const int nChannels = desc.bWriteAlpha ? 4 : 3;	const size_t nPixels = (size_t)width * (size_t)height;	// Planar, one array per channel, and sorted by channel NAME: A, B, G, R. A reader that trusts	// file order shows swapped channels if this is wrong, and nothing reports it.	std::vector<CryHalf> planes[4];	for (int c = 0; c < nChannels; ++c)		planes[c].resize(nPixels);	// planeOfComponent[source RGBA component] -> index into planes[]	const int planeOfComponent[4] =	{		(nChannels == 4) ? 3 : 2,   // R		(nChannels == 4) ? 2 : 1,   // G		(nChannels == 4) ? 1 : 0,   // B		0                           // A (only reached when nChannels == 4)	};	const bool bMatrix = desc.bColorMatrix;	const float* m = desc.colorMatrix;	for (int y = 0; y < height; ++y)	{		const CryHalf* pSrc = pRGBA + (size_t)y * (size_t)srcRowStrideTexels * 4;		const size_t dstBase = (size_t)y * (size_t)width;		for (int x = 0; x < width; ++x, pSrc += 4)		{			const size_t d = dstBase + (size_t)x;			if (bMatrix)			{				// The one place a colour transform happens on the CPU: AP1 -> AP0 for the ACES				// container. Done in float and re-quantised to half once, on a pass that is				// already reading every pixel anyway.				const float r = CryConvertHalfToFloat(pSrc[0]);				const float g = CryConvertHalfToFloat(pSrc[1]);				const float b = CryConvertHalfToFloat(pSrc[2]);				planes[planeOfComponent[0]][d] = CryConvertFloatToHalf(m[0] * r + m[1] * g + m[2] * b);				planes[planeOfComponent[1]][d] = CryConvertFloatToHalf(m[3] * r + m[4] * g + m[5] * b);				planes[planeOfComponent[2]][d] = CryConvertFloatToHalf(m[6] * r + m[7] * g + m[8] * b);			}			else			{				planes[planeOfComponent[0]][d] = pSrc[0];				planes[planeOfComponent[1]][d] = pSrc[1];				planes[planeOfComponent[2]][d] = pSrc[2];			}			if (nChannels == 4)				planes[planeOfComponent[3]][d] = pSrc[3];		}	}	EXRHeader header;	InitEXRHeader(&header);	EXRImage image;	InitEXRImage(&image);	unsigned char* channelPtrs[4] = { nullptr, nullptr, nullptr, nullptr };	for (int c = 0; c < nChannels; ++c)		channelPtrs[c] = reinterpret_cast<unsigned char*>(planes[c].data());	image.num_channels = nChannels;	image.width = width;	image.height = height;	image.images = channelPtrs;	EXRChannelInfo channelInfos[4];	memset(channelInfos, 0, sizeof(channelInfos));	const char* const szNames4[4] = { "A", "B", "G", "R" };	const char* const szNames3[3] = { "B", "G", "R" };	for (int c = 0; c < nChannels; ++c)		cry_strcpy(channelInfos[c].name, sizeof(channelInfos[c].name), (nChannels == 4) ? szNames4[c] : szNames3[c]);	int pixelTypes[4] = { TINYEXR_PIXELTYPE_HALF, TINYEXR_PIXELTYPE_HALF, TINYEXR_PIXELTYPE_HALF, TINYEXR_PIXELTYPE_HALF };	header.num_channels = nChannels;	header.channels = channelInfos;	// Both HALF: the data handed over is half and the data in the file is half, so tinyexr	// converts nothing. That is the whole reason the tap stays fp16.	header.pixel_types = pixelTypes;	header.requested_pixel_types = pixelTypes;	header.compression_type = (int)desc.compression;	std::vector<EXRAttribute> attrs;	std::vector<SAttrPayload> payloads;	attrs.reserve(TINYEXR_MAX_CUSTOM_ATTRIBUTES);	payloads.reserve(TINYEXR_MAX_CUSTOM_ATTRIBUTES);	if (desc.bChromaticities)		PushAttribute(attrs, payloads, "chromaticities", "chromaticities", desc.chromaticities, 8 * (int)sizeof(float));	if (desc.bAcesImageContainerFlag)	{		const int one = 1;		PushAttribute(attrs, payloads, "acesImageContainerFlag", "int", &one, (int)sizeof(int));	}	for (int i = 0; i < desc.numAttributes; ++i)	{		const SExrAttribute& a = desc.pAttributes[i];		switch (a.type)		{		case SExrAttribute::eType_String:			// EXR strings are sized by the attribute length and carry no terminator.			PushAttribute(attrs, payloads, a.name.c_str(), "string", a.sValue.c_str(), (int)a.sValue.length());			break;		case SExrAttribute::eType_Float:			PushAttribute(attrs, payloads, a.name.c_str(), "float", &a.fValue, (int)sizeof(float));			break;		case SExrAttribute::eType_Int:			PushAttribute(attrs, payloads, a.name.c_str(), "int", &a.nValue, (int)sizeof(int));			break;		}	}	BindAttributePayloads(attrs, payloads);	header.num_custom_attributes = (int)attrs.size();	header.custom_attributes = attrs.empty() ? nullptr : attrs.data();	unsigned char* pMemory = nullptr;	const char* szErr = nullptr;	const size_t nSize = SaveEXRImageToMemory(&image, &header, &pMemory, &szErr);	// Everything above is stack- or vector-owned, so neither FreeEXRHeader nor FreeEXRImage may be	// called here - they would free memory tinyexr never allocated.	if (nSize == 0 || pMemory == nullptr)	{		CryLogAlways("[EXR] '%s': tinyexr failed to encode (%s)", szFileName, szErr ? szErr : "no message");		if (szErr)			FreeEXRErrorMessage(szErr);		free(pMemory);		return false;	}	if (szErr)		FreeEXRErrorMessage(szErr);	const bool bOk = WriteFileThroughPak(szFileName, pMemory, nSize);	free(pMemory);	if (!bOk)		CryLogAlways("[EXR] '%s': could not be written (%u bytes)", szFileName, (unsigned)nSize);	return bOk;}void ExrSelfTest(){	// A 4x4 pattern with one negative value (AP1 content legitimately produces those) and one far	// outside [0,1], so a writer that silently clamped would be caught.	const int W = 4, H = 4;	CryHalf rgba[W * H * 4];	for (int y = 0; y < H; ++y)	{		for (int x = 0; x < W; ++x)		{			const int i = (y * W + x) * 4;			rgba[i + 0] = CryConvertFloatToHalf(0.25f * (float)x);			rgba[i + 1] = CryConvertFloatToHalf(0.5f * (float)y);			rgba[i + 2] = CryConvertFloatToHalf((x == 0 && y == 0) ? -0.125f : 128.0f);			rgba[i + 3] = CryConvertFloatToHalf(1.0f);		}	}	SExrWriteDesc desc;	desc.compression = eExrCompression_ZIP;	desc.bWriteAlpha = false;	desc.bChromaticities = true;	// AP1 (ACEScg), the same numbers the capture path uses.	const float ap1[8] = { 0.713f, 0.293f, 0.165f, 0.830f, 0.128f, 0.044f, 0.32168f, 0.33767f };	memcpy(desc.chromaticities, ap1, sizeof(ap1));	SExrAttribute attrs[2];	attrs[0] = SExrAttribute::String("rec/selfTest", "ReC Sandbox S6");	attrs[1] = SExrAttribute::Float("rec/selfTestValue", 1.875f);	desc.pAttributes = attrs;	desc.numAttributes = 2;	CryPathString resolved;	gEnv->pCryPak->AdjustFileName("%USER%/ExrSelfTest.exr", resolved, ICryPak::FLAGS_PATH_REAL | ICryPak::FLAGS_FOR_WRITING);	const char* szResolved = resolved.c_str();	if (!WriteEXR(szResolved, W, H, rgba, W, desc))	{		CryLogAlways("[EXR] self-test FAILED: could not write '%s'", szResolved);		return;	}	// Read it back with tinyexr's own loader. LoadEXR returns float RGBA whatever the file holds,	// which is exactly the independent decode this check wants.	float* pOut = nullptr;	int w = 0, h = 0;	const char* szErr = nullptr;	const int ret = LoadEXR(&pOut, &w, &h, szResolved, &szErr);	if (ret != TINYEXR_SUCCESS || !pOut)	{		CryLogAlways("[EXR] self-test FAILED: read back failed (%s)", szErr ? szErr : "no message");		if (szErr)			FreeEXRErrorMessage(szErr);		free(pOut);		return;	}	if (szErr)		FreeEXRErrorMessage(szErr);	bool bPixelsOk = (w == W && h == H);	float fMaxErr = 0.0f;	if (bPixelsOk)	{		for (int i = 0; i < W * H; ++i)		{			for (int c = 0; c < 3; ++c)			{				const float expected = CryConvertHalfToFloat(rgba[i * 4 + c]);				fMaxErr = max(fMaxErr, fabsf(pOut[i * 4 + c] - expected));			}		}		// Half in, half out, no conversion anywhere: this has to be exact, not close.		bPixelsOk = (fMaxErr == 0.0f);	}	free(pOut);	// The attributes are the half of this that actually needed proving. tinyexr certainly PARSES	// custom attributes; the open question in the research note was whether its WRITER emits them.	int nAttrsFound = 0;	{		std::vector<unsigned char> fileData;		if (FILE* pFile = gEnv->pCryPak->FOpen(szResolved, "rb", ICryPak::FOPEN_ONDISK))		{			gEnv->pCryPak->FSeek(pFile, 0, SEEK_END);			const long nLen = gEnv->pCryPak->FTell(pFile);			gEnv->pCryPak->FSeek(pFile, 0, SEEK_SET);			if (nLen > 0)			{				fileData.resize((size_t)nLen);				gEnv->pCryPak->FReadRaw(fileData.data(), 1, fileData.size(), pFile);			}			gEnv->pCryPak->FClose(pFile);		}		EXRVersion version;		EXRHeader header;		InitEXRHeader(&header);		const char* szErr2 = nullptr;		if (!fileData.empty() &&		    ParseEXRVersionFromMemory(&version, fileData.data(), fileData.size()) == TINYEXR_SUCCESS &&		    ParseEXRHeaderFromMemory(&header, &version, fileData.data(), fileData.size(), &szErr2) == TINYEXR_SUCCESS)		{			for (int i = 0; i < header.num_custom_attributes; ++i)			{				const EXRAttribute& a = header.custom_attributes[i];				if (!strcmp(a.name, "chromaticities") || !strcmp(a.name, "rec/selfTest") || !strcmp(a.name, "rec/selfTestValue"))					++nAttrsFound;			}			FreeEXRHeader(&header);		}		if (szErr2)			FreeEXRErrorMessage(szErr2);	}	if (bPixelsOk && nAttrsFound == 3)		CryLogAlways("[EXR] self-test PASSED: %dx%d half ZIP round-tripped exactly, 3/3 attributes survived ('%s')", W, H, szResolved);	else		CryLogAlways("[EXR] self-test FAILED: pixels %s (max err %g), attributes %d/3 ('%s')",		             bPixelsOk ? "ok" : "wrong", fMaxErr, nAttrsFound, szResolved);}